#include "semantic.h"
#include "library.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
#include <stdexcept>
using namespace semantic;
static void check(bool value,const char* label){if(!value)throw std::runtime_error(label);std::cout<<label<<"=PASS\n";}
static Selection selection(QString id,QString word="reader"){return std::make_shared<const SelectionSnapshot>(QJsonObject{{"document",id},{"pageId",QString(64,'a')},{"page",0},{"id",QString(64,'b')},{"generation","1"},{"text",word.toUpper()},{"word",word},{"sentence","A READER USES BOOKS."}});}
static Result define(const std::filesystem::path& app,const std::filesystem::path& data,Selection selected){Worker worker(app,data);auto page=std::make_shared<PageState>();check(worker.request(Result::Define,page,selected),"define_job_queued");Result result;bool found=false;for(int i=0;i<2000&&!found;++i){found=worker.poll(result);if(!found)std::this_thread::sleep_for(std::chrono::milliseconds(1));}check(found&&worker.finish(2000),"define_job_completed");return result;}
int main(int argc,char**argv){QCoreApplication app(argc,argv);if(argc!=2)return 2;std::filesystem::path root=argv[1];QTemporaryDir temp;check(temp.isValid(),"private_test_root");std::filesystem::path data=temp.path().toStdString();auto dictionary=root/"assets/dictionary/wordnet.ibd",fixture=root/"fixtures/dictionary-test.json";
 library::Store store(data/"library");auto book=store.importDocument(root/"fixtures/inkbound-device-test.pdf","Fixture imported as production document",[](const auto&,const auto&){return library::Inspection{2,"mupdf-1.28.3-pdf-fixed-v1",{}};});auto bookData=library::documentRoot(data/"library",book.id);auto chosen=selection(book.id);
 auto result=define(root,bookData,chosen);check(!result.error&&result.data["status"]=="FOUND"&&result.data["provider"]=="princeton-wordnet-3.0"&&result.data["definition"]=="a person who enjoys reading","production_worker_reaches_real_dictionary");
 auto vocab=loadVocabulary(bookData);auto record=vocab["records"].toArray().first().toObject();check(record["datasetVersion"]=="3.0"&&record["occurrences"].toArray().first().toObject()["document"]==book.id,"vocabulary_keeps_stable_document_id");
 result=define(root,bookData,chosen);check(!result.error&&result.data["vocabularyCount"].toInt()==2&&loadVocabulary(bookData)["records"].toArray().size()==1,"production_capture_deduplicates");
 auto legacy=data/"legacy";auto legacySelected=selection(underlay::FixtureHash);check(lookupAndCapture(fixture,legacy,legacySelected)["provider"]=="inkbound-authored-test-v1","explicit_fixture_provider_retained");auto prior=loadVocabulary(legacy);auto records=prior["records"].toArray();record=records[0].toObject();record.remove("datasetVersion");records[0]=record;prior["records"]=records;writeChecked(legacy/"vocabulary.json",prior);check(loadVocabulary(legacy)["records"].toArray().size()==1,"old_fixture_record_remains_readable");
 auto upgraded=lookupAndCapture(dictionary,legacy,legacySelected);check(upgraded["provider"]=="princeton-wordnet-3.0"&&upgraded["vocabularyCount"].toInt()==2,"existing_record_count_preserved_with_real_lookup");
 auto mixed=lookupAndCapture(fixture,legacy,selection(underlay::FixtureHash,"page"));check(mixed["status"]=="FOUND"&&loadVocabulary(legacy)["records"].toArray().size()==2,"mixed_fixture_wordnet_records_readable");
 result=define(root,data/"qualification",legacySelected);check(!result.error&&result.data["provider"]=="inkbound-authored-test-v1","qualification_worker_explicit_fixture");
 auto before=underlay::readBounded(bookData/"vocabulary.json",2*1024*1024);auto missing=lookupAndCapture(dictionary,bookData,selection(book.id,"unattestedlexemezzzz"));check(missing["status"]=="MISS"&&underlay::readBounded(bookData/"vocabulary.json",2*1024*1024)==before,"miss_does_not_change_vocabulary");
 underlay::privateDirectory(data/"missing-app/fixtures");std::filesystem::copy_file(fixture,data/"missing-app/fixtures/dictionary-test.json");underlay::privateDirectory(data/"missing-app/assets/dictionary");std::filesystem::copy_file(root/"assets/dictionary/gcide.ibd",data/"missing-app/assets/dictionary/gcide.ibd");{library::Store fallbackStore(data/"fallback-library");auto fallbackBook=fallbackStore.importDocument(root/"fixtures/inkbound-device-test.pdf","GCIDE production fallback fixture",[](const auto&,const auto&){return library::Inspection{2,"mupdf-1.28.3-pdf-fixed-v1",{}};});auto fallbackData=library::documentRoot(data/"fallback-library",fallbackBook.id);result=define(data/"missing-app",fallbackData,selection(fallbackBook.id,"would"));check(!result.error&&result.data["status"]=="FOUND"&&result.data["provider"]=="gnu-gcide-0.54"&&result.data["datasetVersion"]=="0.54"&&!result.data["definition"].toString().isEmpty(),"production_worker_uses_real_gcide_when_wordnet_missing");auto captured=loadVocabulary(fallbackData)["records"].toArray();check(captured.size()==1&&captured.first().toObject()["provider"]=="gnu-gcide-0.54","fallback_capture_keeps_actual_source");result=define(data/"missing-app",fallbackData,selection(fallbackBook.id,"would"));check(!result.error&&result.data["provider"]=="gnu-gcide-0.54"&&result.data["vocabularyCount"].toInt()==2,"fallback_capture_reopens_and_deduplicates");result=define(root,fallbackData,selection(fallbackBook.id));check(!result.error&&result.data["provider"]=="princeton-wordnet-3.0"&&loadVocabulary(fallbackData)["records"].toArray().size()==2,"mixed_gcide_wordnet_vocabulary_reopens");}std::filesystem::remove(data/"missing-app/assets/dictionary/gcide.ibd");result=define(data/"missing-app",bookData,chosen);check(!result.error&&result.data["status"]=="UNAVAILABLE"&&result.data["provider"]=="inkbound-offline-cascade-v1"&&underlay::readBounded(bookData/"vocabulary.json",2*1024*1024)==before,"missing_all_production_assets_never_falls_back_to_authored_fixture");
 auto wrong=selection("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");result=define(root,bookData,wrong);check(result.error&&underlay::readBounded(bookData/"vocabulary.json",2*1024*1024)==before,"foreign_document_selection_rejected");
 auto invalid=loadVocabulary(bookData);records=invalid["records"].toArray();record=records[0].toObject();record["provider"]="unknown-provider";records[0]=record;invalid["records"]=records;writeChecked(bookData/"vocabulary.json",invalid);bool rejected=false;try{(void)loadVocabulary(bookData);}catch(...){rejected=true;}check(rejected,"unknown_provider_rejected");underlay::atomicFile(bookData/"vocabulary.json",before);
}
